 function levelUp(){if(state!=='playing')return;state='levelup';const opts=[...UPGRADES].sort(()=>Math.random()-.5).slice(0,3);showPanel(`<div class="eyebrow">Level ${game.player.level} · pick one upgrade</div><div class="title" style="font-size:clamp(30px,6vw,46px)">LEVEL <span class="accent">UP!</span></div><div class="grid">${opts.map((u,i)=>`<div class="pick" data-up="${i}"><div class="emoji">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}</p></div>`).join('')}</div>`);panel.querySelectorAll('[data-up]').forEach((el,i)=>el.onclick=()=>{opts[i].apply(game.player);sound(700,.12,'triangle');state='playing';overlay.classList.add('hidden');updateHud()})}
 function waveShop(){if(game.wave>=10){gameOver(true);return}state='shop';game.wave++;game.waveTime=30;game.spawn=1;game.bossSpawned=false;game.rerolls=0;game.reroll=6+game.wave*2;game.shopItems=makeShop();renderShop()}
